36	// Decrements the induced degree of each neighbor of a peeled vertex. cond stops
37	// the decrementing once a vertex reaches degree 0, so degrees never go
38	// negative: a vertex at 0 has already been (or is about to be) peeled.
39	struct Update_Deg {
40	  intE* Degrees;
41	  Update_Deg(intE* _Degrees) : Degrees(_Degrees) {}
42	  inline bool update (uintE s, uintE d) {
43	    Degrees[d]--;
44	    return 1;
45	  }
46	  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
47	    writeAdd(&Degrees[d],(intE)-1);
48	    return 1;
49	  }
50	  inline bool cond (uintE d) { return Degrees[d] > 0; }
51	};
52	
53	// Selects the vertices to peel in this round: those whose induced degree has
54	// dropped below k. Removing a vertex here records its core number (k-1) and
55	// zeroes its degree so that it is excluded from the remaining subset and from
56	// any further decrements.
57	template <class vertex>
58	struct Deg_LessThan_K {
59	  vertex* V;
60	  uintE* coreNumbers;
61	  intE* Degrees;
62	  long k;
63	  Deg_LessThan_K(vertex* _V, intE* _Degrees, uintE* _coreNumbers, long _k) :
64	    V(_V), k(_k), Degrees(_Degrees), coreNumbers(_coreNumbers) {}
65	  inline bool operator () (uintE i) {
66	    if(Degrees[i] < k) { coreNumbers[i] = k-1; Degrees[i] = 0; return 1; }
67	    else return 0;
68	  }
69	};
70	
71	// Selects the vertices that survive this round, i.e. the ones still having
72	// induced degree at least k. Peeled vertices have degree 0 and so drop out.
73	template <class vertex>
74	struct Deg_AtLeast_K {
75	  vertex* V;
76	  intE* Degrees;
77	  long k;
78	  Deg_AtLeast_K(vertex* _V, intE* _Degrees, long _k) :
79	    V(_V), k(_k), Degrees(_Degrees) {}
80	  inline bool operator () (uintE i) {
81	    return Degrees[i] >= k;
82	  }
83	};
