116		edgeMap(GA,toRemove,Update_Deg(Degrees),-1,no_output);
117		toRemove.del();
118	      }
119	    }
120	    if (Frontier.numNonzeros() == 0) { largestCore = k-1; break; }
121	  }
122	
123	  cout << "largestCore was " << largestCore << endl;
124	  cout << "KCore max core: " << largestCore << endl;
125	
126	  Frontier.del(); free(coreNumbers); free(Degrees);
127	}
